const PROJECT_TEXT={"card": {"title": "Domination", "es": [{"h": "", "p": ["Domination es un juego de cartas desarrollado para mi asignatura de Diseño de Juegos.", "En este proyecto, me encargué del diseño de la parte frontal y trasera de cada una de las cartas de la baraja, el diseño de la identidad de marca y su presentación y caja.", "Utilicé Adobe Illustrator, Adobe Photoshop y Procreate para crear el diseño de las cartas.", "Aquí se puede ver la presentación del proyecto, imágenes del desarrollo y mockups del producto final."]}], "en": [{"h": "", "p": ["Domination is a card game developed for my Game Design class.", "I designed the front and back of every card in the deck, the brand identity, the project presentation and the packaging.", "I used Adobe Illustrator, Adobe Photoshop and Procreate to create the card designs.", "Here you can explore the project presentation, development photographs and mockups of the finished product."]}], "tools": ["Adobe Illustrator", "Adobe Photoshop", "Procreate"]}, "bauhaus": {"title": "Bauhaus", "es": [{"h": "Técnicas", "p": ["Técnicas mixtas artesanales."]}, {"h": "", "p": ["El cartel fue elaborado con distintas técnicas físicas en honor al legado de la propia escuela de diseño Bauhaus.", "Se utilizaron pinturas acrílicas para el fondo, recortes de cartulinas y una técnica de collage para la silueta inspirada en el famoso Ballet Triádico de la Bauhaus. El texto y algunos detalles finales fueron superpuestos con rotuladores y recortes de letras.", "Las decisiones de diseño responden a los principios estéticos de la Bauhaus. Se ha optado por colores primarios —rojo, azul y amarillo— por su valor simbólico dentro del movimiento. La tipografía sans serif refuerza la claridad y funcionalidad del diseño, mientras que la composición asimétrica aporta dinamismo. La figura central organiza el resto de la composición y dirige la atención del espectador."]}], "en": [{"h": "Techniques", "p": ["Handcrafted mixed media."]}, {"h": "", "p": ["The poster was made using a range of physical techniques to honour the legacy of the Bauhaus design school.", "I used acrylic paint for the background, coloured paper cutouts and collage for the silhouette inspired by the famous Triadic Ballet. Lettering and final details were layered onto the poster using markers and cutout letters.", "The design decisions follow Bauhaus aesthetic principles. Primary colours —red, blue and yellow— reflect their symbolic value within the movement. Sans serif typography reinforces clarity and function, while the asymmetrical composition adds movement. The central figure organises the composition and directs the viewer’s attention."]}], "tools": ["Acrylic paint", "Collage", "Mixed media"]}, "greenpeace": {"title": "Greenpeace", "es": [{"h": "Técnicas", "p": ["Collage y photobashing en Adobe Photoshop."]}, {"h": "", "p": ["El cartel fue diseñado y bocetado en Adobe Photoshop, utilizando imágenes de stock de Internet. Busca representar una campaña de protesta contra la industria textil mediante un lenguaje no verbal."]}], "en": [{"h": "Techniques", "p": ["Collage and photobashing in Adobe Photoshop."]}, {"h": "", "p": ["The poster was sketched and designed in Adobe Photoshop using stock images sourced online. It represents a protest campaign against the textile industry through nonverbal visual communication."]}], "tools": ["Adobe Photoshop"]}, "sabadell-sign": {"title": "Sabadell × San Isidro", "es": [{"h": "Técnicas", "p": ["Ilustración y vectorización en Adobe Illustrator; edición en Adobe Photoshop."]}, {"h": "", "p": ["Cartelería diseñada para una campaña de marketing que relaciona las fiestas madrileñas de San Isidro con Banco Sabadell.", "Las piezas se idearon para una acción publicitaria que promociona la Ruta del Clavel, una ruta personalizada creada para las fiestas de San Isidro.", "Diseñé y generé distintas opciones de cartelería."]}], "en": [{"h": "Techniques", "p": ["Illustration and vector artwork in Adobe Illustrator; editing in Adobe Photoshop."]}, {"h": "", "p": ["Posters designed for a marketing campaign connecting Madrid’s San Isidro celebrations with Banco Sabadell.", "The pieces promote the Ruta del Clavel, a bespoke route created for the festivities as part of an advertising activation.", "I designed and developed several poster options."]}], "tools": ["Adobe Illustrator", "Adobe Photoshop"]}, "scary": {"title": "Scary Movie", "es": [{"h": "Técnicas", "p": ["Ilustración y vectorización en Adobe Illustrator."]}, {"h": "", "p": ["Cartel ilustrado para la película Scary Movie, con un dibujo realizado íntegramente con vectores en Illustrator para mi asignatura de Integración de Herramientas."]}], "en": [{"h": "Techniques", "p": ["Illustration and vector artwork in Adobe Illustrator."]}, {"h": "", "p": ["An illustrated poster for Scary Movie, drawn entirely with vectors in Illustrator for my Tools Integration class."]}], "tools": ["Adobe Illustrator"]}, "stay": {"title": "Stay High / Habits", "es": [{"h": "", "p": ["Elaborado con Adobe Photoshop y Adobe Illustrator.", "El cartel, basado en la canción Stay High (Habits) de Tove Lo, representa la evasión emocional a través de la exageración y distorsión tipográfica. La palabra HIGH se convierte en el elemento dominante de la composición, inflada y deformada, simbolizando el efecto artificial del subidón, el momento de euforia de las drogas.", "La repetición constante de HIGH no solo hace referencia al ritmo del remix, sino también al pensamiento obsesivo y compulsivo del protagonista. La deformación progresiva de todas las palabras sugiere una pérdida de estabilidad y una percepción alterada de la realidad. El degradado aplicado a HIGH refuerza la idea de elevación y expansión, pero también introduce una sensación de irrealidad y mareo, como algo brillante pero artificial. Además, el efecto de inflar le da una sensación mucho más etérea y desconcertante. También lo he considerado un pequeño de juego de palabras, ya que se le da el aspecto de un globo y “high”, además de drogado, también puede significar alto o arriba.", "La tipografía Franklin Gothic transmite fuerza, contundencia y presencia visual. El peso tipográfico aporta un cierto impacto y hace que el mensaje sea directo y agresivo. La jerarquía visual está claramente marcada por el tamaño. “You’re gone so I gotta stay” funcionan como introducción (o al menos la parte legible, el resto está expandido y funciona como fondo), mientras que HIGH domina la composición por escala y repetición. El aumento de tamaño no solo establece jerarquía, sino que simboliza la importancia emocional que tiene ese estado alterado en la narrativa. La distorsión aplicada a las palabras simboliza una percepción alterada, inestabilidad emocional y pérdida de control. No se trata de una deformación decorativa, sino de una deformación conceptual: refleja el estado mental del protagonista. El degradado en HIGH sugiere volumen y expansión, reforzando la idea de elevación artificial. Visualmente, es capaz de crear un contraste con el resto del texto y acentúa su protagonismo."]}], "en": [{"h": "Tools", "p": ["Adobe Photoshop and Adobe Illustrator."]}, {"h": "", "p": ["Based on Tove Lo’s song Stay High (Habits), this poster represents emotional escapism through exaggerated, distorted typography. HIGH becomes the dominant element: inflated and warped to symbolise an artificial high and the euphoric moment produced by drugs.", "The constant repetition of HIGH echoes both the rhythm of the remix and the protagonist’s obsessive, compulsive thoughts. The progressive distortion of all the words suggests instability and an altered perception of reality. The gradient reinforces elevation and expansion, while introducing a dizzying sense of unreality: something bright but artificial. The inflated effect feels ethereal and disorienting. It also creates a small visual pun: the word resembles a balloon, and “high” can mean both intoxicated and physically elevated.", "Franklin Gothic communicates strength, impact and a strong visual presence. Its weight makes the message direct and aggressive. Size establishes the hierarchy: “You’re gone so I gotta stay” forms the introduction, at least where it is still legible, while the expanded text also becomes a background. HIGH dominates through scale and repetition. Its enlargement symbolises the emotional importance of this altered state within the narrative. The distorted words reflect altered perception, emotional instability and loss of control. This is conceptual rather than purely decorative distortion: it expresses the protagonist’s state of mind. The gradient suggests volume and expansion, reinforces artificial elevation and contrasts with the surrounding text to emphasise the word’s prominence."]}], "tools": ["Adobe Photoshop", "Adobe Illustrator"]}, "series": {"title": "Sandy Sinner", "es": [{"h": "Tipo de proyecto", "p": ["Transmedia · Animación · Diseño de personajes"]}, {"h": "Descripción", "p": ["Sandy Sinner es una propuesta de serie de animación desarrollada como proyecto transmedia. El proyecto parte de la creación de un universo narrativo propio, trabajando tanto la identidad visual de la historia como sus personajes, escenarios y desarrollo audiovisual."]}, {"h": "Mi rol", "p": ["Participé en el desarrollo visual y narrativo del proyecto, especialmente en la creación del universo, diseño de personajes y elaboración del storyboard, buscando mantener una estética y personalidad coherentes a lo largo de toda la propuesta."]}, {"h": "Qué hice", "list": ["Worldbuilding y desarrollo del universo visual.", "Diseño y caracterización de personajes.", "Exploración estética y referencias visuales.", "Storyboard de escenas.", "Desarrollo de la narrativa visual."], "p": ["Este proyecto me permitió transformar un universo ficticio en algo visual, construyendo su personalidad a través de los personajes, los escenarios y la narrativa."]}], "en": [{"h": "Project type", "p": ["Transmedia · Animation · Character Design"]}, {"h": "Description", "p": ["Sandy Sinner is an animated series proposal developed as a transmedia project. It starts with an original narrative universe, exploring the story’s visual identity alongside its characters, settings and audiovisual development."]}, {"h": "My role", "p": ["I contributed to the project’s visual and narrative development, particularly its worldbuilding, character design and storyboard, working to maintain a coherent aesthetic and personality throughout the proposal."]}, {"h": "What I did", "list": ["Worldbuilding and development of the visual universe.", "Character design and characterisation.", "Aesthetic exploration and visual references.", "Storyboarding scenes.", "Development of the visual narrative."]}, {"h": "", "p": ["This project allowed me to turn a fictional universe into a visual world, building its personality through characters, settings and storytelling."]}], "tools": []}, "sabadell": {"title": "Sabadell × San Isidro", "es": [{"h": "Tipo de proyecto", "p": ["Campaña de marketing · Concepto creativo · Publicidad exterior"]}, {"h": "Descripción", "p": ["Campaña de marketing desarrollada para Banco Sabadell con motivo de San Isidro 2026. El objetivo fue conectar la marca con una de las celebraciones más reconocibles de Madrid mediante una propuesta cercana, urbana y vinculada a la cultura local.", "La campaña combina estrategia, concepto creativo y diseño visual a través de diferentes puntos de contacto con el público, trasladando la identidad de Sabadell al contexto de las fiestas de San Isidro."]}, {"h": "Mi rol", "p": ["Desarrollé el concepto creativo de la campaña, su enfoque estratégico y la adaptación visual a diferentes soportes físicos y acciones de calle."]}, {"h": "Qué hice", "list": ["Investigación de marca y contexto cultural.", "Desarrollo del concepto creativo.", "Diseño de campaña gráfica.", "Creación de tres acciones de street marketing.", "Cartelería y publicidad exterior.", "Adaptación de la campaña a distintos formatos y soportes.", "Desarrollo de mockups para visualizar la campaña en contexto."], "p": []}, {"h": "Objetivo", "p": ["Crear una campaña capaz de acercar Banco Sabadell a un público más joven y urbano, utilizando San Isidro como punto de conexión entre tradición madrileña, experiencia de marca y comunicación contemporánea."]}], "en": [{"h": "Project type", "p": ["Marketing Campaign · Creative Concept · Outdoor Advertising"]}, {"h": "Description", "p": ["A marketing campaign developed for Banco Sabadell for San Isidro 2026. Its aim was to connect the brand with one of Madrid’s most recognisable celebrations through an approachable, urban proposal rooted in local culture.", "The campaign combines strategy, creative concept and visual design across different audience touchpoints, bringing Sabadell’s identity into the context of the San Isidro festivities."]}, {"h": "My role", "p": ["I developed the campaign’s creative concept, strategic approach and visual adaptations for physical formats and street activations."]}, {"h": "What I did", "list": ["Brand and cultural context research.", "Development of the creative concept.", "Graphic campaign design.", "Creation of three street marketing activations.", "Posters and outdoor advertising.", "Adaptation to different formats and media.", "Mockups to visualise the campaign in context."]}, {"h": "Objective", "p": ["To bring Banco Sabadell closer to a younger, urban audience, using San Isidro to connect Madrid’s traditions, brand experience and contemporary communication."]}], "tools": []}, "madrid": {"title": "Madrid merece mais dias", "es": [{"h": "Tipo de proyecto", "p": ["Dirección de arte · Desarrollo visual · Campaña turística"]}, {"h": "Descripción", "p": ["Madrid merece mais dias es una campaña turística dirigida al mercado brasileño premium que presenta Madrid como una ciudad que merece ser vivida con más tiempo, a través de experiencias culturales, gastronómicas, artísticas y de ocio. La propuesta busca transmitir una imagen de Madrid elegante, cálida, sofisticada y vibrante."]}, {"h": "Mi rol", "p": ["Dirección de arte y desarrollo visual.", "Me encargué de construir el universo visual de la campaña, definiendo una identidad coherente capaz de transmitir una Madrid premium, emocional y contemporánea. Desarrollé el estilo fotográfico, la paleta cromática, las tipografías, las composiciones, la iconografía y los criterios visuales aplicados a las diferentes piezas de comunicación."]}, {"h": "Qué hice", "list": ["Investigación y creación de moodboards.", "Definición de la dirección de arte.", "Desarrollo de la paleta de color y sistema tipográfico.", "Definición del estilo fotográfico y tratamiento de imagen.", "Desarrollo de composiciones y layouts.", "Creación del sistema visual e iconográfico.", "Bocetado y desarrollo del key visual.", "Adaptación de la identidad a soportes impresos, digitales y redes sociales.", "Desarrollo visual de cartelería, revistas, mupis, banners y contenido para RRSS."], "p": []}, {"h": "Concepto visual", "p": ["La dirección de arte se inspira en el lenguaje editorial de las revistas internacionales de lifestyle y turismo de lujo. Se utilizan fotografías cálidas y cinematográficas,", "composiciones limpias, amplios espacios negativos y una jerarquía visual clara para representar Madrid desde una perspectiva más íntima, aspiracional y sofisticada."]}, {"h": "Resultado", "p": ["Un sistema visual consistente y adaptable que mantiene la misma personalidad en todos los puntos de contacto de la campaña: premium, emocional, vibrante, elegante y humano."]}], "en": [{"h": "Project type", "p": ["Art Direction · Visual Development · Tourism Campaign"]}, {"h": "Description", "p": ["Madrid merece mais dias is a tourism campaign for the premium Brazilian market. It presents Madrid as a city worth experiencing for longer through culture, gastronomy, art and leisure. The proposal communicates an elegant, warm, sophisticated and vibrant image of Madrid."]}, {"h": "My role", "p": ["Art direction and visual development.", "I built the campaign’s visual universe and a coherent identity for a premium, emotional and contemporary Madrid. I developed its photographic style, colour palette, typography, compositions, iconography and the visual criteria applied across its communication pieces."]}, {"h": "What I did", "list": ["Research and moodboard creation.", "Definition of the art direction.", "Development of the colour palette and typographic system.", "Definition of the photographic style and image treatment.", "Development of compositions and layouts.", "Creation of the visual and iconographic system.", "Sketching and development of the key visual.", "Adaptation of the identity to print, digital media and social platforms.", "Visual development of posters, magazines, outdoor displays, banners and social content."]}, {"h": "Visual concept", "p": ["The art direction takes inspiration from international lifestyle and luxury travel magazines. Warm, cinematic photography, clean compositions, generous negative space and clear visual hierarchy represent Madrid from a more intimate, aspirational and sophisticated perspective."]}, {"h": "Result", "p": ["A consistent, adaptable visual system that carries the same personality across every campaign touchpoint: premium, emotional, vibrant, elegant and human."]}], "tools": []}, "ui": {"title": "Dungeon Crawler Carl", "es": [{"h": "Tipo de proyecto", "p": ["Diseño UI · Sistema de diseño · Interfaz de videojuego"]}, {"h": "Descripción", "p": ["Diseño de un sistema de interfaz para una adaptación de Carl el Mazmorrero como videojuego RPG dungeon crawler. El objetivo fue crear una UI capaz de organizar información compleja de gameplay de forma clara, rápida y coherente, manteniendo al mismo tiempo una identidad visual alineada con el tono oscuro, caótico y competitivo del universo del juego."]}, {"h": "Mi rol", "p": ["Diseño de interfaz y desarrollo del sistema visual.", "Trabajé en la construcción de un sistema UI completo, desde sus fundamentos visuales hasta la aplicación final en pantallas de juego. El proyecto se desarrolló siguiendo una estructura modular basada en Foundations, Components, Patterns y Screens, permitiendo mantener coherencia y reutilización en toda la interfaz."]}, {"h": "Qué hice", "list": ["Desarrollo del sistema cromático y jerarquías de color.", "Definición de tipografía y estilos de texto.", "Creación de grid y sistema de espaciado.", "Desarrollo de iconografía.", "Creación de variables y design tokens.", "Diseño de componentes reutilizables.", "Desarrollo de barras de vida y maná, botones, minimapa, tarjetas de objetos, pop- ups e indicadores de combate.", "Creación de patrones de navegación e interacción.", "Diseño de flujos de inicio, combate e inventario.", "Diseño de HUD y pantallas finales.", "Prototipado y organización del sistema en Figma."], "p": []}, {"h": "Enfoque", "p": ["El sistema se diseñó priorizando la lectura rápida de información durante el gameplay. La jerarquía visual permite identificar inmediatamente elementos críticos como la salud, enemigos, temporizadores, objetivos y estados activos, reduciendo la carga visual durante situaciones de combate y exploración."]}, {"h": "Resultado", "p": ["Un sistema de interfaz modular y escalable capaz de construir diferentes pantallas y situaciones de juego sin perder consistencia visual ni funcional."]}], "en": [{"h": "Project type", "p": ["UI Design · Design System · Game Interface"]}, {"h": "Description", "p": ["An interface system for an RPG dungeon crawler adaptation of Dungeon Crawler Carl. The goal was to organise complex gameplay information clearly, quickly and consistently, while keeping a visual identity aligned with the dark, chaotic and competitive tone of the game’s universe."]}, {"h": "My role", "p": ["Interface design and visual system development.", "I worked on a complete UI system, from its visual foundations to the final game screens. The project follows a modular structure of Foundations, Components, Patterns and Screens, supporting consistency and reuse throughout the interface."]}, {"h": "What I did", "list": ["Development of the colour system and colour hierarchy.", "Definition of typography and text styles.", "Creation of a grid and spacing system.", "Iconography development.", "Creation of variables and design tokens.", "Design of reusable components.", "Development of health and mana bars, buttons, a minimap, item cards, pop-ups and combat indicators.", "Creation of navigation and interaction patterns.", "Design of start, combat and inventory flows.", "Design of the HUD and final screens.", "Prototyping and organisation of the system in Figma."]}, {"h": "Approach", "p": ["The system prioritises fast reading during gameplay. Its hierarchy makes critical elements such as health, enemies, timers, objectives and active states immediately recognisable, reducing visual load during combat and exploration."]}, {"h": "Result", "p": ["A modular, scalable interface system that can support different screens and gameplay situations while preserving visual and functional consistency."]}], "tools": ["Figma"]}, "report": {"title": "Ai Weiwei — Editorial Reportage", "es": [{"h": "Tipo de proyecto", "p": ["Diseño editorial · Maquetación de revista · Dirección de arte"]}, {"h": "Descripción", "p": ["Diseño y maquetación editorial de un reportaje sobre el artista Ai Weiwei. El proyecto transforma un contenido periodístico extenso en una propuesta visual clara y dinámica, combinando texto, fotografía, citas destacadas y diferentes estructuras de página para mantener el ritmo de lectura.", "El reportaje aborda la trayectoria personal y artística de Ai Weiwei, su relación con el activismo, el exilio, la censura y su visión del mundo del arte."]}, {"h": "Mi rol", "p": ["Diseño editorial y maquetación.", "Me encargué de construir la identidad visual del reportaje y de organizar todo el contenido mediante una estructura editorial coherente. Trabajé la jerarquía de títulos, cuerpos de texto, citas e imágenes para crear una lectura visualmente atractiva sin perder claridad."]}, {"h": "Qué hice", "list": ["Diseño y maquetación completa del reportaje.", "Creación de retículas y estructura editorial.", "Desarrollo de jerarquías tipográficas.", "Selección, tratamiento y composición de imágenes.", "Diseño de portada y aperturas de sección.", "Integración de citas destacadas dentro de la narrativa visual.", "Composición de páginas con diferentes ritmos y proporciones.", "Uso del blanco y negro como recurso visual para reforzar el carácter del reportaje."], "p": []}, {"h": "Enfoque visual", "p": ["La propuesta utiliza una estética editorial sobria y de alto contraste, con predominio del blanco y negro. Las composiciones alternan páginas con grandes imágenes, columnas de texto, citas destacadas y espacios en blanco para generar ritmo y reforzar el carácter del contenido."]}, {"h": "Resultado", "p": ["Un reportaje editorial visualmente consistente que equilibra contenido periodístico e imagen, permitiendo una lectura clara y manteniendo una identidad gráfica sólida a lo largo de todas las páginas."]}], "en": [{"h": "Project type", "p": ["Editorial Design · Magazine Layout · Art Direction"]}, {"h": "Description", "p": ["Editorial design and layout of a reportage about artist Ai Weiwei. The project transforms extensive journalistic content into a clear, dynamic visual proposal, combining text, photography, pull quotes and varied page structures to maintain a rhythm of reading.", "The reportage explores Ai Weiwei’s personal and artistic journey, his relationship with activism, exile and censorship, and his view of the art world."]}, {"h": "My role", "p": ["Editorial design and layout.", "I built the report’s visual identity and organised the content into a coherent editorial structure. I developed the hierarchy of headings, body text, quotes and images to create a visually engaging reading experience without sacrificing clarity."]}, {"h": "What I did", "list": ["Complete design and layout of the reportage.", "Creation of grids and editorial structure.", "Development of typographic hierarchy.", "Image selection, treatment and composition.", "Design of the cover and section openings.", "Integration of pull quotes into the visual narrative.", "Page compositions with different rhythms and proportions.", "Use of black and white to reinforce the report’s character."]}, {"h": "Visual approach", "p": ["A restrained, high-contrast editorial aesthetic dominated by black and white. Large images, text columns, pull quotes and white space alternate to establish rhythm and reinforce the character of the content."]}, {"h": "Result", "p": ["A visually consistent editorial reportage that balances journalism and imagery, enabling clear reading and a strong graphic identity across all its pages."]}], "tools": ["Adobe InDesign"]}, "memo": {"title": "Ballet Triádico — Bauhaus", "es": [{"h": "Tipo de proyecto", "p": ["Diseño de cartel · Investigación visual · Inspiración Bauhaus"]}, {"h": "Descripción", "p": ["Diseño de un cartel publicitario inspirado en el Ballet Triádico de Oskar Schlemmer y en los principios visuales de la Bauhaus. El proyecto parte de una investigación histórica y gráfica para reinterpretar la obra desde una mirada contemporánea.", "El concepto se construye a partir del contraste entre dos ideas: la rigidez geométrica de la Bauhaus y la fluidez del movimiento del ballet. Esta dualidad guía tanto la composición como la construcción de la figura principal."]}, {"h": "Mi rol", "p": ["Investigación visual, desarrollo conceptual y diseño gráfico del cartel."]}, {"h": "Qué hice", "list": ["Investigación sobre Bauhaus, Oskar Schlemmer y el Ballet Triádico.", "Búsqueda y análisis de referencias gráficas.", "Desarrollo del concepto creativo.", "Creación de moodboards y referencias visuales.", "Exploración mediante bocetos.", "Construcción de la figura principal con formas geométricas.", "Definición de composición, color y tipografía.", "Desarrollo y producción del cartel final."], "p": []}, {"h": "Concepto visual", "p": ["La pieza utiliza formas geométricas, colores primarios y una composición asimétrica inspirada en el lenguaje visual de la Bauhaus. La figura central representa el cuerpo convertido en geometría, mientras que la línea curva introduce movimiento y rompe con la rigidez de la composición."]}, {"h": "Resultado", "p": ["Un cartel que combina estructura y movimiento, reinterpretando el lenguaje visual de la Bauhaus a través de una composición contemporánea vinculada al Ballet Triádico."]}], "en": [{"h": "Project type", "p": ["Poster Design · Visual Research · Bauhaus-inspired Design"]}, {"h": "Description", "p": ["An advertising poster inspired by Oskar Schlemmer’s Triadic Ballet and Bauhaus visual principles. Historical and graphic research form the basis for a contemporary reinterpretation of the work.", "The concept contrasts two ideas: the geometric rigidity of Bauhaus and the fluidity of ballet movement. This duality guides the composition and the construction of the central figure."]}, {"h": "My role", "p": ["Visual research, concept development and graphic design of the poster."]}, {"h": "What I did", "list": ["Research into Bauhaus, Oskar Schlemmer and the Triadic Ballet.", "Search and analysis of graphic references.", "Development of the creative concept.", "Creation of moodboards and visual references.", "Exploration through sketches.", "Construction of the central figure with geometric shapes.", "Definition of composition, colour and typography.", "Development and production of the final poster."]}, {"h": "Visual concept", "p": ["Geometric shapes, primary colours and an asymmetrical composition draw on the Bauhaus visual language. The central figure turns the body into geometry, while the curved line introduces movement and breaks the rigidity of the composition."]}, {"h": "Result", "p": ["A poster that combines structure and movement, reinterpreting the Bauhaus visual language through a contemporary composition connected to the Triadic Ballet."]}], "tools": []}, "florario": {"title": "Florario de Diseño", "es": [{"h": "Tipo de proyecto", "p": ["Diseño editorial · Dirección de arte · Experimentación visual"]}, {"h": "Descripción", "p": ["Florario de diseñadores es una antología editorial que reinterpreta visualmente la obra de diferentes diseñadores y artistas a través de un universo botánico común.", "El proyecto nace de la idea de transformar a cada diseñador en una “flor” distinta, manteniendo su identidad individual pero integrándola dentro de un mismo lenguaje visual. La propuesta combina diseño editorial, collage, ilustración, fotografía y elementos artesanales para convertir la publicación en una experiencia visual y física."]}, {"h": "Mi rol", "p": ["Dirección de arte · Diseño editorial · Ilustración · Maquetación", "Desarrollé el proyecto completo desde la conceptualización inicial hasta su producción física: investigación, dirección artística, diseño de identidad, creación de las portadillas de cada diseñador, maquetación editorial y encuadernación final."]}, {"h": "Concepto creativo", "p": ["La identidad de Florario se construye sobre tres ideas principales:", "Organicidad + editorial Contrastar elementos naturales, pétalos, flores y texturas con estructuras editoriales ordenadas y jerarquías gráficas claras.", "Crafty + luxury Combinar procesos y recursos visuales de carácter artesanal —collage, texturas, materiales y composición manual— con una estética cuidada y elegante.", "Reinterpretación visual Traducir el lenguaje gráfico de cada diseñador a una representación floral diferente, creando una identidad propia para cada sección dentro de un universo común."]}, {"h": "Qué hice", "list": ["Investigación visual y conceptual.", "Brainstorming y desarrollo de mapas conceptuales.", "Definición del público objetivo.", "Creación de moodboards.", "Desarrollo de la identidad visual de la publicación.", "Diseño de portada, contraportada, guardas e índice.", "Diseño de portadillas individuales.", "Reinterpretación visual del estilo de cada diseñador.", "Ilustración y composición gráfica en Illustrator.", "Diseño de citas y elementos tipográficos.", "Maquetación editorial.", "Selección y tratamiento de imágenes.", "Desarrollo de color y sistema tipográfico.", "Preparación de archivos finales para impresión.", "Producción y encuadernación física de la publicación."], "p": []}, {"h": "Diseñadores reinterpretados", "p": ["Takashi Murakami · Milton Glaser · Neville Brody · Saul Bass · Herb Lubalin · Jimmy Choo · Jonas Cozone · Tim Burton.", "Cada sección desarrolla una identidad gráfica diferente inspirada en el lenguaje visual del diseñador, pero mantiene elementos comunes que permiten reconocer todas las piezas como parte de Florario."]}, {"h": "Dirección de arte", "p": ["La dirección artística mezcla feminidad, naturaleza, collage, diseño editorial y experimentación gráfica. El contraste entre composiciones limpias y elementos orgánicos permite mantener una estética delicada sin perder expresividad.", "La flor funciona como hilo conductor del proyecto y cambia visualmente en función del diseñador representado."]}, {"h": "Tipografías", "p": ["Amoresa — títulos Helvetica Bold — subtítulos Helvetica Regular — cuerpo de texto"]}, {"h": "Paleta principal", "p": ["Crema — #FDFDF1 Rosa — #EDA1BF"]}, {"h": "Formato", "p": ["Publicación cuadrada de 20 × 20 cm, elegida para reforzar el carácter artístico y experimental de la antología."]}, {"h": "Proceso", "p": ["El proyecto comenzó con una fase de investigación y exploración visual mediante brainstorming, mapas conceptuales y moodboards. A partir de ahí desarrollé primero la identidad general de Florario y posteriormente una propuesta gráfica específica para cada diseñador.", "Las portadillas fueron desarrolladas principalmente en Illustrator, combinando referencias de cada artista con elementos botánicos, collage y composición editorial. Posteriormente se diseñaron las páginas informativas y las citas para construir una publicación coherente de principio a fin."]}, {"h": "Resultado", "p": ["Una antología que funciona tanto como publicación editorial como objeto artístico. El proyecto combina diseño gráfico, experimentación visual y artesanía editorial dentro de una narrativa visual unificada y reconocible."]}], "en": [{"h": "Project type", "p": ["Editorial Design · Art Direction · Visual Experimentation"]}, {"h": "Description", "p": ["Florario de diseñadores is an editorial anthology that visually reinterprets the work of different designers and artists through a shared botanical universe.", "Each designer becomes a different “flower”, retaining an individual identity within a common visual language. The project combines editorial design, collage, illustration, photography and handcrafted elements to turn the publication into both a visual and a physical experience."]}, {"h": "My role", "p": ["Art direction · Editorial design · Illustration · Layout.", "I developed the entire project, from its initial concept to physical production: research, artistic direction, identity design, individual designer section openings, editorial layout and final binding."]}, {"h": "Creative concept", "p": ["The identity of Florario is built around three main ideas.", "Organic + editorial: natural elements, petals, flowers and textures contrast with ordered editorial structures and clear graphic hierarchies.", "Crafty + luxury: handcrafted processes —collage, textures, materials and manual composition— combine with a carefully considered, elegant aesthetic.", "Visual reinterpretation: each designer’s graphic language becomes a different floral representation, giving each section its own identity within a shared universe."]}, {"h": "What I did", "list": ["Visual and conceptual research.", "Brainstorming and concept maps.", "Definition of the target audience.", "Creation of moodboards.", "Development of the publication’s visual identity.", "Design of cover, back cover, endpapers and contents.", "Design of individual section openings.", "Visual reinterpretation of each designer’s style.", "Illustration and graphic composition in Illustrator.", "Design of quotes and typographic elements.", "Editorial layout.", "Image selection and treatment.", "Development of colour and typography systems.", "Preparation of final print files.", "Physical production and binding."]}, {"h": "Reinterpreted designers", "p": ["Takashi Murakami · Milton Glaser · Neville Brody · Saul Bass · Herb Lubalin · Jimmy Choo · Jonas Cozone · Tim Burton.", "Each section has a different graphic identity inspired by its designer’s visual language, while shared elements identify all the pieces as part of Florario."]}, {"h": "Art direction", "p": ["The art direction combines femininity, nature, collage, editorial design and graphic experimentation. The contrast between clean compositions and organic elements maintains a delicate yet expressive aesthetic.", "The flower is the thread running through the project, changing visually according to the designer it represents."]}, {"h": "Visual system", "p": ["Amoresa — titles. Helvetica Bold — subtitles. Helvetica Regular — body text.", "Main palette: cream #FDFDF1 and pink #EDA1BF.", "Format: a square 20 × 20 cm publication, chosen to reinforce the anthology’s artistic and experimental character."]}, {"h": "Process", "p": ["The project began with research and visual exploration through brainstorming, concept maps and moodboards. I then developed Florario’s overall identity and a specific graphic proposal for each designer.", "The section openings were developed mainly in Illustrator, combining references to each artist with botanical elements, collage and editorial composition. The information pages and quotes then formed a coherent publication from beginning to end."]}, {"h": "Result", "p": ["An anthology that works as both an editorial publication and an art object, combining graphic design, visual experimentation and editorial craft in a unified, recognisable narrative."]}], "tools": ["Adobe Illustrator", "Adobe InDesign"]}, "author": {"title": {"es": "La separación entre obra y autor", "en": "Separating the work from its author"}, "es": [{"h": "Tipo de proyecto", "p": ["Ensayo académico · Análisis cultural · Estética"]}, {"h": "Descripción", "p": ["Ensayo académico centrado en el debate sobre si una obra puede separarse realmente de la figura de su autor. El texto analiza cómo la intención del creador, su identidad pública y", "el contexto social y moral influyen en la manera en la que interpretamos y valoramos una obra."]}, {"h": "Pregunta principal", "p": ["¿Es posible separar una obra de su autor, o nuestra interpretación está inevitablemente condicionada por la imagen que construimos de quien la crea?"]}, {"h": "Enfoque", "p": ["El ensayo contrapone dos perspectivas teóricas principales. Por un lado, E. D. Hirsch defiende que la interpretación está vinculada a la intención del autor; por otro, Roland Barthes plantea la autonomía de la obra y el papel activo del espectador en la construcción de significado."]}, {"h": "Qué trabajé", "list": ["Investigación teórica sobre estética y recepción.", "Comparación de posturas opuestas.", "Análisis de la relación entre autor, obra y espectador.", "Reflexión sobre identidad pública y construcción mediática.", "Análisis ético del consumo cultural.", "Aplicación de teoría a casos contemporáneos.", "Desarrollo de una postura crítica personal."], "p": []}, {"h": "Casos analizados", "p": ["Ye · J. K. Rowling · Woody Allen · Pablo Picasso."]}, {"h": "Conclusión", "p": ["El ensayo plantea que no existe una respuesta universal. Aunque una obra puede adquirir significados independientes de su creador, en la sociedad contemporánea resulta difícil eliminar por completo la influencia de la identidad, las acciones y el contexto moral del autor. La relación entre ambos depende también de la experiencia, valores y vínculo emocional del espectador."]}], "en": [{"h": "Project type", "p": ["Academic Essay · Cultural Analysis · Aesthetics"]}, {"h": "Description", "p": ["An academic essay examining whether a work can truly be separated from its author. It analyses how the creator’s intentions, public identity and social and moral context shape our interpretation and evaluation of a work."]}, {"h": "Main question", "p": ["Can we separate a work from its author, or is our interpretation inevitably shaped by the image we construct of its creator?"]}, {"h": "Approach", "p": ["The essay contrasts two main theoretical perspectives. E. D. Hirsch links interpretation to authorial intention, while Roland Barthes proposes the autonomy of the work and the viewer’s active role in constructing meaning."]}, {"h": "What I explored", "list": ["Theoretical research into aesthetics and reception.", "Comparison of opposing viewpoints.", "Analysis of the author–work–viewer relationship.", "Reflection on public identity and media representation.", "Ethical analysis of cultural consumption.", "Application of theory to contemporary cases.", "Development of a personal critical position."]}, {"h": "Cases analysed", "p": ["Ye · J. K. Rowling · Woody Allen · Pablo Picasso."]}, {"h": "Conclusion", "p": ["There is no universal answer. A work can acquire meanings independently of its creator, but in contemporary society it is difficult to remove the influence of the author’s identity, actions and moral context completely. Their relationship also depends on the viewer’s experiences, values and emotional connection."]}], "tools": []}, "undertale": {"title": {"es": "Pánico moral, desensibilización y violencia", "en": "Moral panic, desensitisation and violence"}, "es": [{"h": "Tipo de proyecto", "p": ["Ensayo crítico · Estudios de videojuegos · Análisis de medios"]}, {"h": "Descripción", "p": ["Ensayo de análisis sobre la relación entre videojuegos, violencia y desensibilización, utilizando Undertale como principal caso de estudio.", "El artículo parte del concepto de pánico moral y analiza cómo diferentes medios —desde los cómics y Dungeons & Dragons hasta los videojuegos— han sido señalados históricamente como responsables de comportamientos violentos o de la corrupción de los jóvenes."]}, {"h": "Pregunta principal", "p": ["¿La violencia en los videojuegos desensibiliza al jugador, o puede la propia interactividad utilizarse para cuestionar nuestra relación con la violencia?"]}, {"h": "Enfoque", "p": ["El ensayo diferencia entre la exposición pasiva a contenidos violentos y la desensibilización interactiva, propia de los videojuegos, donde el jugador no solo observa una acción, sino que participa activamente en ella.", "A partir de ahí, el análisis se centra en cómo los RPG convierten muchas veces la violencia en una mecánica de progreso rutinaria y cómo Undertale subvierte precisamente esa lógica."]}, {"h": "Qué trabajé", "list": ["Investigación sobre pánico moral.", "Historia de la percepción social de los videojuegos.", "Análisis de violencia y desensibilización.", "Estudio de la interactividad como elemento narrativo.", "Análisis de mecánicas propias de los RPG.", "Estudio de narrativa y metanarrativa.", "Análisis de decisiones morales dentro del gameplay.", "Reflexión sobre empatía, agencia y responsabilidad del jugador."], "p": []}, {"h": "Caso principal: Undertale", "p": ["El ensayo analiza cómo Undertale convierte decisiones aparentemente simples —atacar, perdonar, reiniciar una partida— en elementos con peso narrativo y moral. El juego cuestiona las convenciones tradicionales de los RPG y crea una relación directa entre las acciones del jugador y las consecuencias que experimenta el mundo del juego."]}, {"h": "Ruta genocida y metanarrativa", "p": ["La ruta genocida funciona como el núcleo del análisis. La repetición de la violencia transforma la eliminación de enemigos en una tarea mecánica, mientras el propio mundo pierde progresivamente música, personajes y estímulos. El juego convierte así la desensibilización en parte de su discurso y confronta directamente al jugador con su comportamiento."]}, {"h": "Conclusión", "p": ["El análisis propone que el problema no está simplemente en la presencia de violencia dentro de un videojuego, sino en la relación que el jugador construye con ella. Undertale demuestra cómo la interactividad puede utilizarse no solo para representar violencia, sino también para cuestionarla y generar reflexión sobre empatía, responsabilidad y agencia."]}], "en": [{"h": "Project type", "p": ["Critical Essay · Game Studies · Media Analysis"]}, {"h": "Description", "p": ["An analytical essay about video games, violence and desensitisation, using Undertale as its main case study.", "Starting with moral panic, it examines how media ranging from comics and Dungeons & Dragons to video games have historically been blamed for violent behaviour or the corruption of young people."]}, {"h": "Main question", "p": ["Does violence in video games desensitise the player, or can interactivity itself question our relationship with violence?"]}, {"h": "Approach", "p": ["The essay distinguishes passive exposure to violent content from interactive desensitisation in games, where the player actively participates rather than simply observes.", "It then examines how RPGs often turn violence into a routine progression mechanic, and how Undertale subverts that logic."]}, {"h": "What I explored", "list": ["Research into moral panic.", "History of society’s perception of video games.", "Analysis of violence and desensitisation.", "Interactivity as a narrative element.", "Analysis of RPG mechanics.", "Narrative and metanarrative.", "Moral choices in gameplay.", "Reflection on empathy, agency and player responsibility."]}, {"h": "Main case: Undertale", "p": ["The essay examines how seemingly simple decisions —attacking, sparing or restarting a game— acquire narrative and moral weight. Undertale challenges traditional RPG conventions and connects the player’s actions directly to consequences in the game world."]}, {"h": "Genocide route and metanarrative", "p": ["The genocide route is central to the analysis. Repeated violence turns eliminating enemies into a mechanical task, while the world progressively loses music, characters and stimuli. Desensitisation becomes part of the game’s argument as it directly confronts the player with their behaviour."]}, {"h": "Conclusion", "p": ["The issue is not simply the presence of violence in a game, but the relationship the player develops with it. Undertale shows how interactivity can represent violence, question it and prompt reflection on empathy, responsibility and agency."]}], "tools": []}, "tattoo": {"title": {"en": "Tattoo design", "es": "Diseño de tatuajes"}, "es": [{"h": "", "p": ["Me gustan mucho los tatuajes y estoy aprendiendo a tatuar. Me encanta diseñar tatuajes para mí y para mis amigos, y en un futuro pretendo realizarlos también sobre la piel, practicando la técnica del tatuaje. Aquí se pueden ver algunos de mis diseños más recientes."]}], "en": [{"h": "", "p": ["I love tattoos and I’m learning how to tattoo. I enjoy designing tattoos for myself and my friends, and I hope to bring them from digital drawings onto skin as I develop my tattooing skills. Here are some of my most recent designs."]}], "tools": []}, "drawings": {"title": {"en": "Custom drawings", "es": "Dibujos personalizados"}, "es": [{"h": "", "p": ["Me encanta dibujar e iré subiendo aquí dibujos realizados con distintas técnicas a lo largo del año."]}], "en": [{"h": "", "p": ["I love drawing, and I’ll keep adding work made with different techniques throughout the year."]}], "tools": []}};
